const NAVOF={articles:'lib',article:'lib',zadi:'home',sawm:'home',quran:'quran',read:'quran',hifz:'quran',ward:'quran',khatma:'quran',bookmarks:'quran',reciters:'quran',hifzhelp:'quran',adhkar:'adhkar',tasbeeh:'adhkar',duas:'adhkar',duacat:'adhkar',mythkr:'adhkar',sleep:'adhkar',khalwa:'adhkar',goals:'adhkar',athkarvoice:'adhkar',lib:'lib',myfile:'lib',pdfs:'lib',pdf:'lib',books:'lib',book:'lib',library:'lib'};
