const IDB=()=>new Promise((res,rej)=>{const r=indexedDB.open('zadlib',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
const idbPut=async o=>{const db=await IDB();return new Promise((res,rej)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(o);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})};
const idbGet=async id=>{const db=await IDB();return new Promise((res,rej)=>{const q=db.transaction('files').objectStore('files').get(id);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})};
const idbDel=async id=>{const db=await IDB();return new Promise(res=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>res();tx.onerror=()=>res()})};
