let JSZ=null;const loadZip=()=>JSZ||(JSZ=new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js';s.onload=()=>res(window.JSZip);s.onerror=()=>{JSZ=null;rej(new Error('jszip'))};document.head.appendChild(s)}));
const TXTC={};
function cleanHTML(doc){const out=[];const walk=n=>{for(const c of n.children){const tg=c.tagName.toLowerCase();if(/^(script|style|img|svg|image|nav|figure|head)$/.test(tg))continue;if(/^h[1-6]$/.test(tg)){const t=c.textContent.trim();t&&out.push(`<h3>${esc(t)}</h3>`)}else if(/^(p|li|blockquote|pre)$/.test(tg)){const t=c.textContent.trim();t&&out.push(`<p>${esc(t)}</p>`)}else if(c.children.length)walk(c);else{const t=c.textContent.trim();t&&out.push(`<p>${esc(t)}</p>`)}}};walk(doc.body||doc.documentElement);return out.join('')}
async function textOf(m){if(TXTC[m.id])return TXTC[m.id];const rec=await idbGet(m.id);if(!rec)throw new Error('missing');let html='';
 if(m.kind==='txt'){const t=await rec.blob.text();html=t.split(/\r?\n\s*\r?\n/).map(p=>p.trim()).filter(Boolean).map(p=>`<p>${esc(p).replace(/\r?\n/g,'<br>')}</p>`).join('')}
 else{const JZ=await loadZip();const z=await JZ.loadAsync(rec.blob);const cont=await z.file('META-INF/container.xml').async('string');const opfP=/full-path="([^"]+)"/.exec(cont)[1];const base=opfP.includes('/')?opfP.slice(0,opfP.lastIndexOf('/')+1):'';const opf=new DOMParser().parseFromString(await z.file(opfP).async('string'),'application/xml');const man={};opf.querySelectorAll('manifest > item, item').forEach(i=>man[i.getAttribute('id')]=i.getAttribute('href'));
  const parts=[];for(const r of opf.querySelectorAll('itemref')){const h=man[r.getAttribute('idref')];if(!h)continue;const f=z.file(decodeURIComponent(base+h))||z.file(base+h);if(!f)continue;const doc=new DOMParser().parseFromString(await f.async('string'),'text/html');parts.push(cleanHTML(doc))}html=parts.filter(Boolean).join('<hr style="border:0;border-top:1px solid var(--line);margin:2em 0">')}
 return TXTC[m.id]=html||'<p>الملف فارغ</p>'}
