 let tm=0;const onS=()=>{if(!document.getElementById('ztx')){removeEventListener('scroll',onS);return}const p=Math.min(1,scrollY/maxS());$('#tpr').style.width=Math.round(p*100)+'%';clearTimeout(tm);tm=setTimeout(()=>{m.pos=+p.toFixed(4);save()},400)};addEventListener('scroll',onS,{passive:true});
